def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    freq = Counter(v for row in grid for v in row)
    bg = freq.most_common(1)[0][0]

    # Find periodic separator rows and columns: lines differ from the
    # uniform tile interiors and recur at a fixed pitch.
    def find_pitch(axis):
        n = h if axis == 0 else w
        other = w if axis == 0 else h
        best = None
        for p in range(2, min(n, 12) + 1):
            for off in range(p):
                score = 0
                for k in range(off, n, p):
                    vals = ([grid[k][j] for j in range(w)] if axis == 0
                            else [grid[j][k] for j in range(h)])
                    if sum(v != bg for v in vals) >= 2:
                        score += 1
                if best is None or score > best[0]:
                    best = (score, p, off)
        return best[1], best[2]

    ph, oh = find_pitch(0)
    pw, ow = find_pitch(1)

    # Interior sample gives each output cell's ordinary color.
    nr = max(1, (h - oh) // ph)
    nc = max(1, (w - ow) // pw)
    out = []
    for r in range(nr):
        row = []
        for c in range(nc):
            rr = min(h - 1, oh + r * ph + ph // 2)
            cc = min(w - 1, ow + c * pw + pw // 2)
            row.append(grid[rr][cc])
        out.append(row)

    # Colored marks at lattice intersections overwrite the corresponding
    # output cell.
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            if (r - oh) % ph == 0 and (c - ow) % pw == 0:
                ri = (r - oh) // ph
                ci = (c - ow) // pw
                if 0 <= ri < nr and 0 <= ci < nc:
                    out[ri][ci] = v
    return out
