def transform(grid):
    h, w = len(grid), len(grid[0])
    # Lattice spacing is indicated by the regular background tiles.
    rh, cw = 3, 4
    nr, nc = (h - 1) // rh, (w - 1) // cw
    out = [[7 for _ in range(nc)] for _ in range(nr)]

    # Paired colored points along a lattice boundary encode output cells.
    # A horizontal pair is read at its left endpoint; row boundaries after
    # the first correspond to the cell immediately above that boundary.
    for r in range(0, h, rh):
        for c in range(0, w - cw, cw):
            v = grid[r][c]
            if v not in (0, 7) and grid[r][c + cw] == v:
                rr = r // rh
                if rr > 0:
                    rr -= 1
                cc = c // cw
                if 0 <= rr < nr and 0 <= cc < nc:
                    out[rr][cc] = v
    return out
